WITH own_tasks AS (SELECT TASK_ID AS task_id FROM CFG_TASKS WHERE PIPELINE_ID=CAST(:pipeline_id AS bigint)),
wanted_tasks AS (SELECT TASK_ID AS task_id FROM own_tasks UNION SELECT DEPENDS_ON_TASK_ID AS task_id FROM CFG_TASK_DEPENDENCY WHERE TASK_ID IN (SELECT TASK_ID FROM own_tasks)),
wanted_pipelines AS (SELECT CAST(:pipeline_id AS bigint) AS pipeline_id UNION SELECT PIPELINE_ID AS pipeline_id FROM CFG_TASKS WHERE TASK_ID IN (SELECT TASK_ID FROM wanted_tasks) UNION SELECT DEPENDS_ON_PIPELINE_ID AS pipeline_id FROM CFG_PIPELINE_DEPENDENCY WHERE PIPELINE_ID=CAST(:pipeline_id AS bigint)),
wanted_tables AS (SELECT TARGET_TABLE_ID AS table_id FROM CFG_TASKS WHERE TASK_ID IN (SELECT TASK_ID FROM wanted_tasks) UNION SELECT TARGET_TABLE_ID AS table_id FROM CFG_BUSINESS_RULES WHERE TASK_ID IN (SELECT TASK_ID FROM own_tasks))
SELECT CAST(jsonb_build_object('_version',2,'CFG_PIPELINES',jsonb_build_object('columns',CAST('["pipeline_id", "pipeline_code", "pipeline_name", "description", "run_schedule", "sla_in_hours", "refresh_type", "active_flag", "pipeline_parameters", "created_by", "create_date", "updated_by", "updated_date", "schedule_timezone", "catchup", "max_catchup_runs", "overlap_policy", "schedule_start_date", "max_parallel_tasks", "priority", "project_id", "block_on_refresh_error", "calendar_id", "non_business_day", "stewardable_flag"]' AS jsonb),'rows',COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM (SELECT p.* FROM wanted_pipelines w CROSS JOIN LATERAL (SELECT * FROM CFG_PIPELINES p WHERE p.PIPELINE_ID=w.PIPELINE_ID LIMIT 1) p ORDER BY p.pipeline_id) r),'[]'::jsonb)),
'CFG_TASKS',jsonb_build_object('columns',CAST('["task_id", "task_code", "task_type", "pipeline_id", "handler", "run_condition", "run_condition_count", "active_flag", "created_by", "create_date", "updated_by", "updated_date", "target_table_id", "target_active_flag"]' AS jsonb),'rows',COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM (SELECT * FROM CFG_TASKS WHERE TASK_ID IN (SELECT TASK_ID FROM wanted_tasks) ORDER BY task_id) r),'[]'::jsonb)),
'CFG_TASK_PARAMETERS',jsonb_build_object('columns',CAST('["task_parameter_id", "task_id", "parameter_name", "parameter_value", "active_flag", "created_by", "create_date", "updated_by", "updated_date"]' AS jsonb),'rows',COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM (SELECT * FROM CFG_TASK_PARAMETERS WHERE TASK_ID IN (SELECT TASK_ID FROM own_tasks) ORDER BY task_parameter_id) r),'[]'::jsonb)),
'CFG_TASK_DEPENDENCY',jsonb_build_object('columns',CAST('["task_dependency_id", "pipeline_id", "task_id", "depends_on_pipeline_id", "depends_on_task_id", "dependency_type", "active_flag", "created_by", "create_date", "updated_by", "updated_date", "consume_repairs"]' AS jsonb),'rows',COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM (SELECT * FROM CFG_TASK_DEPENDENCY WHERE TASK_ID IN (SELECT TASK_ID FROM own_tasks) ORDER BY task_dependency_id) r),'[]'::jsonb)),
'CFG_PIPELINE_DEPENDENCY',jsonb_build_object('columns',CAST('["pipeline_dependency_id", "pipeline_id", "depends_on_pipeline_id", "dependency_type", "active_flag", "created_by", "create_date", "updated_by", "updated_date", "consume_repairs"]' AS jsonb),'rows',COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM (SELECT * FROM CFG_PIPELINE_DEPENDENCY WHERE PIPELINE_ID=CAST(:pipeline_id AS bigint) ORDER BY pipeline_dependency_id) r),'[]'::jsonb)),
'CFG_BUSINESS_RULES',jsonb_build_object('columns',CAST('["business_rule_id", "business_rule_name", "pipeline_id", "task_id", "business_rule_sql", "business_rule_type", "business_rule_key_column", "business_rule_level", "sequence_number", "active_flag", "created_by", "create_date", "updated_by", "updated_date", "target_table_id"]' AS jsonb),'rows',COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM (SELECT * FROM CFG_BUSINESS_RULES WHERE TASK_ID IN (SELECT TASK_ID FROM own_tasks) ORDER BY business_rule_id) r),'[]'::jsonb)),
'CFG_TABLES',jsonb_build_object('columns',CAST('["table_id", "catalog_name", "schema_name", "table_name", "object_kind", "active_flag", "created_by", "create_date", "updated_by", "updated_date", "project_id", "reject_retention_days", "snapshot_retention_days", "orphan_retention_days"]' AS jsonb),'rows',COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM (SELECT * FROM CFG_TABLES WHERE TABLE_ID IN (SELECT TABLE_ID FROM wanted_tables) ORDER BY table_id) r),'[]'::jsonb)),
'CFG_COLUMNS',jsonb_build_object('columns',CAST('["column_id", "table_id", "column_name", "data_type", "column_position", "is_nullable", "active_flag", "created_by", "create_date", "updated_by", "updated_date"]' AS jsonb),'rows',COALESCE((SELECT jsonb_agg(to_jsonb(r)) FROM (SELECT * FROM CFG_COLUMNS WHERE TABLE_ID IN (SELECT TABLE_ID FROM wanted_tables) ORDER BY column_id) r),'[]'::jsonb))) AS text) AS snapshot
